package db

// Learning-session identifiers are generated by the server. Sessions opened
// before this rule may carry an identifier chosen by an API client; closing
// every open session makes the next start_learning_session issue a fresh,
// server-generated identifier. Closed history stays referenced by its
// evidence rows and is never rewritten.
const sqliteCloseOpenLearningSessionsMigration = `UPDATE learning_sessions
SET status = 'closed', closed_at = COALESCE(closed_at, last_active_at)
WHERE status = 'open'`

// learning_sessions forces row-level security for its owner too, so the
// migration binds each tenant in turn, as earlier data migrations do.
const postgresCloseOpenLearningSessionsMigration = `DO $$
DECLARE tenant_row RECORD;
BEGIN
    FOR tenant_row IN SELECT id FROM tenants LOOP
        PERFORM set_config('app.current_tenant', tenant_row.id, true);
        UPDATE learning_sessions
        SET status = 'closed', closed_at = COALESCE(closed_at, last_active_at)
        WHERE status = 'open';
    END LOOP;
    PERFORM set_config('app.current_tenant', '', true);
END $$`

// A confidential DCR client secret is returned once and never stored in a
// recoverable form. The retired replay envelope column is removed together
// with any value it still held.
const sqliteDropDCRReplaySecretMigration = `ALTER TABLE oauth_clients DROP COLUMN registration_secret_ciphertext`

const postgresDropDCRReplaySecretMigration = `ALTER TABLE oauth_clients DROP COLUMN IF EXISTS registration_secret_ciphertext`

// The password-based institution console (browser sessions, TOTP enrolment,
// recovery codes and e-mail password resets of institution users) is
// retired: institutions authenticate with native key identities. Its tables
// hold only credentials and transient sessions, never learning data.
const sqliteDropInstitutionConsoleMigration = `DROP TABLE IF EXISTS console_sessions;
DROP TABLE IF EXISTS user_password_resets;
DROP TABLE IF EXISTS mfa_recovery_codes;
DROP TABLE IF EXISTS mfa_credentials`

const postgresDropInstitutionConsoleMigration = `DROP TABLE IF EXISTS console_sessions;
DROP TABLE IF EXISTS user_password_resets;
DROP TABLE IF EXISTS mfa_recovery_codes;
DROP TABLE IF EXISTS mfa_credentials`

// Institutions are provisioned by the operator (control plane and native
// identities); the self-service signup requests table has no writer left.
const dropPendingSignupsMigration = `DROP TABLE IF EXISTS pending_signups`

// Deleting an expired DCR client must also remove the consents that name it.
// Those consents are tenant-scoped rows under FORCE ROW LEVEL SECURITY, so a
// maintenance transaction bound to one tenant (or to none) cannot see, and
// therefore cannot delete, another tenant's consent; the restricting foreign
// key then blocked the client deletion forever and kept the client counted
// in the registration cap. A cascading foreign key is enforced by
// PostgreSQL's referential-integrity triggers, which run as the table owner
// without row security, so the consent rows of every tenant disappear with
// the client in the same statement. No SECURITY DEFINER function or
// cross-tenant enumeration is needed. SQLite has no row-level security: its
// explicit dependent-row deletion already sees every consent.
const postgresCascadeOAuthClientApprovalsMigration = `DO $$
DECLARE constraint_row RECORD;
BEGIN
    FOR constraint_row IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'learner_approved_clients'::regclass
          AND confrelid = 'oauth_clients'::regclass
          AND contype = 'f'
    LOOP
        EXECUTE format('ALTER TABLE learner_approved_clients DROP CONSTRAINT %I', constraint_row.conname);
    END LOOP;
END $$;
ALTER TABLE learner_approved_clients
    ADD CONSTRAINT learner_approved_clients_client_fk
    FOREIGN KEY (client_id) REFERENCES oauth_clients(client_id) ON DELETE CASCADE`

// Membership invitations and the per-membership second-factor gate had no
// writer left once the institution console was retired: nothing could create
// or accept an invitation, and nothing could record the MFA verification that
// staff memberships (owner, admin, pedagogy manager, trainer) needed before
// they could obtain a principal. The gate therefore only locked such
// memberships out. Institution staff authenticate with native key identities,
// whose key is itself the strong factor.
const sqliteDropMembershipMFAAndInvitationsMigration = `DROP TABLE IF EXISTS invitation_tenant_routes;
DROP TABLE IF EXISTS tenant_invitations;
ALTER TABLE tenant_memberships DROP COLUMN mfa_verified_at;
ALTER TABLE tenant_memberships DROP COLUMN mfa_required`

const postgresDropMembershipMFAAndInvitationsMigration = `DROP TABLE IF EXISTS invitation_tenant_routes;
DROP TABLE IF EXISTS tenant_invitations;
ALTER TABLE tenant_memberships DROP COLUMN IF EXISTS mfa_verified_at;
ALTER TABLE tenant_memberships DROP COLUMN IF EXISTS mfa_required`
